package io.fireflysoftware.common.config.web.tenantbinding;

import io.fireflysoftware.common.config.web.tenantbinding.impl.TenantResourceBindingGovernanceBudgetFilterImpl;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.mock.http.server.reactive.MockServerHttpRequest;
import org.springframework.mock.web.server.MockServerWebExchange;
import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;
import java.time.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

class TenantResourceBindingGovernanceBudgetTest {
    static final class Time extends Clock {Instant now=Instant.parse("2026-11-01T00:00:00Z");long nanos;public Instant instant(){return now;}public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}void advance(long millis){now=now.plusMillis(millis);nanos+=millis*1000000;}}
    @Test void delayedAuthenticationSubscriptionCannotMintAnotherFiveSeconds(){var time=new Time();var filter=new TenantResourceBindingGovernanceBudgetFilterImpl(time,()->time.nanos);var exchange=MockServerWebExchange.from(MockServerHttpRequest.post(TenantResourceBindingGovernanceBudgetFilterImpl.BASE+"/intents"));var calls=new AtomicInteger();var original=filter.filter(exchange,owned->{calls.incrementAndGet();return Mono.empty();});time.advance(5000);StepVerifier.create(original).verifyComplete();assertEquals(0,calls.get());assertEquals(HttpStatus.SERVICE_UNAVAILABLE,exchange.getResponse().getStatusCode());assertEquals("{\"code\":\"TENANT_RESOURCE_BINDING_GOVERNANCE_UNAVAILABLE\"}",exchange.getResponse().getBodyAsString().block());}
    @Test void anObservedCommittedResultSurvivesTheExchangeDeadlineWithoutReleasingItsReceipt(){var time=new Time();var filter=new TenantResourceBindingGovernanceBudgetFilterImpl(time,()->time.nanos);var exchange=MockServerWebExchange.from(MockServerHttpRequest.post(TenantResourceBindingGovernanceBudgetFilterImpl.BASE+"/actions"));var calls=new AtomicInteger();var request=TenantResourceBindingGovernanceHttpTest.REQUEST;var completion=new io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingContracts.Completion(request.intent().control().actionId(),request.originalIntentDigest(),io.fireflysoftware.common.config.core.authority.TenantResourceBindingCodec.reference(request.intent().control().definition()),1,io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingContracts.State.ACTIVE,java.util.UUID.randomUUID(),java.util.UUID.randomUUID(),java.util.UUID.randomUUID());var committed=new io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingGovernedContracts.ActionResult(io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingGovernedContracts.ActionStatus.COMMITTED,request.intent().control().actionId(),request.originalIntentDigest(),null,completion);StepVerifier.withVirtualTime(()->filter.filter(exchange,owned->{calls.incrementAndGet();TenantResourceBindingGovernanceBudgetFilterImpl.retainAction(owned,request);TenantResourceBindingGovernanceBudgetFilterImpl.retainKnownCommit(owned,committed);return Mono.never();})).then(()->time.advance(5000)).thenAwait(Duration.ofSeconds(5)).verifyComplete();assertEquals(1,calls.get());assertEquals(HttpStatus.OK,exchange.getResponse().getStatusCode());String body=exchange.getResponse().getBodyAsString().block();assertTrue(body.contains("\"status\":\"COMMITTED_RESPONSE_UNAVAILABLE\""));assertTrue(body.contains(request.originalIntentDigest()));assertFalse(body.contains(completion.receiptId().toString()));}
    @Test void expiringDispatchedWorkKeepsOnlyOriginalRecoveryIdentityAndCancelsOnce(){var time=new Time();var filter=new TenantResourceBindingGovernanceBudgetFilterImpl(time,()->time.nanos);var exchange=MockServerWebExchange.from(MockServerHttpRequest.post(TenantResourceBindingGovernanceBudgetFilterImpl.BASE+"/actions"));var calls=new AtomicInteger();var cancellations=new AtomicInteger();StepVerifier.withVirtualTime(()->filter.filter(exchange,owned->{calls.incrementAndGet();TenantResourceBindingGovernanceBudgetFilterImpl.retainAction(owned,TenantResourceBindingGovernanceHttpTest.REQUEST);return Mono.<Void>never().doOnCancel(cancellations::incrementAndGet);})).then(()->time.advance(5000)).thenAwait(Duration.ofSeconds(5)).verifyComplete();assertEquals(1,calls.get());assertEquals(1,cancellations.get());assertEquals(HttpStatus.OK,exchange.getResponse().getStatusCode());String body=exchange.getResponse().getBodyAsString().block();assertTrue(body.contains("\"status\":\"OUTCOME_UNKNOWN\""));assertTrue(body.contains(TenantResourceBindingGovernanceHttpTest.REQUEST.originalIntentDigest()));assertTrue(body.contains(TenantResourceBindingGovernanceHttpTest.INTENT.control().actionId().toString()));assertFalse(body.contains("COMMITTED"));}
}
